from math import gcd

def find_solution(a, b, n):
    """
    Returns a tuple (x, y) such that ax + by = n, or None if no solution exists.
    """
    g, x, y = extended_gcd(a, b)
    if n % g != 0:
        return None
    x0 = (x * (n // g)) % (b // g)
    y0 = (y * (n // g)) - (a // g) * x0
    return (x0, y0)

def extended_gcd(a, b):
    """
    Returns the greatest common divisor of a and b, and the coefficients x and y such that ax + by = gcd(a, b).
    """
    if b == 0:
        return (a, 1, 0)
    else:
        g, x1, y1 = extended_gcd(b, a % b)
        x = y1
        y = x1 - (a // b) * y1
        return (g, x, y)
